frappe.pages["amazon-order-display"].on_page_load = function (wrapper) {
	const page = frappe.ui.make_app_page({ parent: wrapper, title: "Amazon 订单概况", single_column: true });
	frappe.require(["assets/fengjing_app/js/主体-echarts.js","assets/fengjing_app/js/map/amazon-order-map.js"], () => new AmazonOrderDashboard(page, wrapper));
};

