	select(id, label) { return `<label>${label}<select id="aod-${id}"><option value="">全部</option></select></label>`; }
	picker(id,label){return `<label class="aod-picker">${label}<input id="aod-${id}" data-picker="${id}" placeholder="全部（可搜索或下拉）" autocomplete="off"><div id="aod-${id}-menu" class="aod-picker-menu"></div></label>`;}
	bind() {
		const root=$(this.wrapper);
		root.on("click","[data-days]",e=>{root.find("[data-days]").removeClass("active");$(e.currentTarget).addClass("active");this.setDates(+e.currentTarget.dataset.days);this.load();});
		root.on("click","#aod-query",()=>this.load()); root.on("keyup","#aod-search-text",e=>{if(e.key==="Enter")this.load();});
		root.on("focus input","[data-picker]",e=>this.showPicker(e.currentTarget.dataset.picker,e.currentTarget.value));root.on("mousedown",".aod-picker-option",e=>{e.preventDefault();const button=e.currentTarget;root.find(`#aod-${button.dataset.kind}`).val(button.dataset.value);root.find(".aod-picker-menu").removeClass("show");});root.on("click",e=>{if(!$(e.target).closest(".aod-picker").length)root.find(".aod-picker-menu").removeClass("show");});
		root.on("click","#aod-reset",()=>{root.find("select").val("");root.find("input[type=text]").val("");this.setDates(30);root.find("[data-days]").removeClass("active").filter('[data-days="30"]').addClass("active");this.load();});
		root.on("input","#aod-local-search",()=>{this.pageNo=1;this.renderTable();}); root.on("click","#aod-prev",()=>{if(this.pageNo>1){this.pageNo--;this.renderTable();}}); root.on("click","#aod-next",()=>{if(this.pageNo*this.pageSize<this.filtered.length){this.pageNo++;this.renderTable();}});
		root.on("click","#aod-export",()=>this.exportCSV()); this.resize=()=>this.charts.forEach(c=>c.resize());window.addEventListener("resize",this.resize);
		root.on("click","#aod-analysis-close",()=>root.find("#aod-analysis-drawer").removeClass("show"));
	}
	setDates(days){const to=frappe.datetime.get_today(),from=days?frappe.datetime.add_days(to,-days):"2025-04-01";$(this.wrapper).find("#aod-from").val(from).end().find("#aod-to").val(to);}
