		const aliases={US:"美国","United States":"美国",Canada:"加拿大",CA:"加拿大",Mexico:"墨西哥",MX:"墨西哥",Brazil:"巴西",BR:"巴西"},scope=new Set((countries||[]).map(country=>aliases[country]||country)),events=[];
