		dynamic(nth(1,1,3),["美国"],"马丁·路德·金纪念日");dynamic(nth(2,1,3),["美国"],"总统日");dynamic(nth(2,0,2),["美国"],"超级碗星期日");dynamic(last(5,1),["美国"],"阵亡将士纪念日");dynamic(nth(9,1,1),["美国","加拿大"],"劳动节 / 劳工节");dynamic(nth(10,1,2),["美国"],"原住民日 / 哥伦布日");
