	isoDate(date){return `${date.getUTCFullYear()}-${String(date.getUTCMonth()+1).padStart(2,"0")}-${String(date.getUTCDate()).padStart(2,"0")}`;}
	easterDate(year){const a=year%19,b=Math.floor(year/100),c=year%100,d=Math.floor(b/4),e=b%4,f=Math.floor((b+8)/25),g=Math.floor((b-f+1)/3),h=(19*a+b-d-g+15)%30,i=Math.floor(c/4),k=c%4,l=(32+2*e+2*i-h-k)%7,m=Math.floor((a+11*h+22*l)/451),month=Math.floor((h+l-7*m+114)/31),day=(h+l-7*m+114)%31+1;return this.isoDate(new Date(Date.UTC(year,month-1,day)));}
	count(rows,key){const out={};rows.forEach(r=>{const k=String(r[key]||"未分类");out[k]=(out[k]||0)+1;});return out;}
	donut(id,data,palette,tooltip){const entries=Object.entries(data).sort((a,b)=>b[1]-a[1]);this.chart(id,{tooltip:{...tooltip,trigger:"item"},legend:{type:"scroll",bottom:0,textStyle:{color:"#526078"}},color:palette,series:[{type:"pie",radius:["48%","72%"],center:["50%","43%"],padAngle:2,itemStyle:{borderRadius:7},label:{formatter:"{b}\n{d}%",color:"#526078"},data:entries.map(([name,value])=>({name,value}))}]});}
	bar(id,data,color,tooltip,limit=8,formatter=null){const entries=Object.entries(data).sort((a,b)=>b[1]-a[1]).slice(0,limit).reverse(),tooltipOption={...tooltip,trigger:"axis",axisPointer:{type:"shadow"}};if(formatter)tooltipOption.formatter=formatter;return this.chart(id,{tooltip:tooltipOption,grid:{left:135,right:25,top:12,bottom:28},xAxis:{type:"value",splitLine:{lineStyle:{color:"#edf2f8"}}},yAxis:{type:"category",data:entries.map(x=>x[0]),axisLabel:{width:122,overflow:"truncate",color:"#526078"}},series:[{type:"bar",data:entries.map(x=>x[1]),barMaxWidth:18,itemStyle:{color,borderRadius:[0,7,7,0]},label:{show:true,position:"right",color:"#526078"}}]});}
	renderTable(){const q=String($(this.wrapper).find("#aod-local-search").val()||"").trim().toLowerCase();this.filtered=this.rows.filter(r=>!q||[r.amazon_order_id,r.sku,r.asin,r.product_name,r.country,r.store,r.shipping_city,r.shipping_postal_code].some(v=>String(v||"").toLowerCase().includes(q)));this.filtered.sort((a,b)=>{let av=a[this.sortKey]??"",bv=b[this.sortKey]??"";if(["quantity_ordered","item_total"].includes(this.sortKey)){av=+av||0;bv=+bv||0;}return(av>bv?1:av<bv?-1:0)*(this.sortDirection==="asc"?1:-1);});const pages=Math.max(1,Math.ceil(this.filtered.length/this.pageSize));this.pageNo=Math.min(this.pageNo,pages);const slice=this.filtered.slice((this.pageNo-1)*this.pageSize,this.pageNo*this.pageSize);$(this.wrapper).find("#aod-count").text(`${this.fmt(this.filtered.length)} 条SKU明细 · ${this.fmt(this.orders.length)} 个订单`);$(this.wrapper).find("#aod-tbody").html(slice.map(r=>this.row(r)).join("")||'<tr><td colspan="10" class="aod-empty">当前条件没有订单</td></tr>');$(this.wrapper).find("#aod-page-info").text(`第 ${this.pageNo} / ${pages} 页`);$(this.wrapper).find("#aod-prev").prop("disabled",this.pageNo<=1);$(this.wrapper).find("#aod-next").prop("disabled",this.pageNo>=pages);}
	row(r){const status=this.statusClass(r.order_status),statusLabel=this.statusText(r.order_status),amount=`${r.currency_code||""} ${this.money(+r.item_total||+r.order_total||0)}`,image=r.item_image?`<img src="${this.esc(r.item_image)}" alt="">`:'<span class="aod-item-placeholder">物</span>',item=r.item_code?`<a href="/app/item/${encodeURIComponent(r.item_code)}" title="${this.esc(r.item_name||r.item_code)}">${this.esc(r.item_name||r.item_code)}</a><small>${this.esc(r.item_code)}</small>`:'<em>未绑定 ERPNext 物料</em>';return `<tr><td><b>${this.esc(this.shortDate(r.purchase_date))}</b><small>${this.esc(String(r.purchase_date||"").slice(11,19))}</small></td><td><a href="/app/amazon-order-synchronization/${encodeURIComponent(r.name)}">${this.esc(r.amazon_order_id||"—")}</a><small>${this.esc(r.amazon_order_item_id||"")}</small></td><td class="aod-product"><b title="${this.esc(r.product_name||"")}">${this.esc(r.product_name||"未返回商品名称")}</b><small>SKU ${this.esc(r.sku||"—")} · ASIN ${this.esc(r.asin||"—")}</small><div class="aod-item-map">${image}<span>${item}</span></div></td><td><span class="aod-status ${status}">${this.esc(statusLabel)}</span></td><td>${this.esc(r.country||r.marketplace_id||"—")}<small>${this.esc(r.store||"—")}</small></td><td>${this.esc(r.fulfillment_channel||"—")}<small>${this.esc(r.ship_service_level||"")}</small></td><td><b>${this.fmt(+r.quantity_ordered||0)}</b><small>已发 ${this.fmt(+r.number_of_items_shipped||0)}</small></td><td><b>${this.esc(amount)}</b><small>订单 ${this.esc(r.currency_code||"")} ${this.money(+r.order_total||0)}</small></td><td>${this.esc([r.shipping_city,r.shipping_state_or_region].filter(Boolean).join(", ")||"—")}<small>${this.esc([r.shipping_country_code,r.shipping_postal_code].filter(Boolean).join(" "))}</small></td><td><span class="aod-sync ${r.sync_status==="成功"?"ok":"bad"}"><i></i>${this.esc(r.sync_status||"未知")}</span><small>${this.esc(this.shortDate(r.fetched_at))}</small></td></tr>`;}
	statusClass(v){v=String(v||"").toUpperCase();return v.includes("SHIP")?"shipped":v.includes("CANCEL")?"cancelled":v.includes("PENDING")?"pending":"other";}
